// Generates src/openai-tools/_manifests.generated.ts by reading the canonical
// OpenAI tool manifests from @sogni-ai/sogni-protocol and emitting them as
// inline TypeScript constants. This avoids ESM JSON-import attribute
// requirements (Node ≥ 22 rejects bare `import x from './foo.json'` without
// `with { type: 'json' }`, which TypeScript cannot emit conditionally for
// dual CJS+ESM builds).
//
// The generated file is .gitignored. Run via `npm run codegen` or as part of
// `npm run build` / `npm install` (via `prepare`).
import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

const require = createRequire(import.meta.url);
const protocolPkg = require.resolve('@sogni-ai/sogni-protocol/package.json');
const protocolManifestsDir = join(dirname(protocolPkg), 'manifests');

const outFile = join(process.cwd(), 'src', 'openai-tools', '_manifests.generated.ts');

const manifestFiles = ['app-tools.json', 'composition-tools.json', 'generation-tools.json'];

const constNameFor = (filename) => {
  const base = filename.replace(/\.json$/, '');
  // generation-tools → generationToolsManifest
  return `${base.replace(/[-_](.)/g, (_, ch) => ch.toUpperCase())}Manifest`;
};

const sections = [];
for (const file of manifestFiles) {
  const raw = await readFile(join(protocolManifestsDir, file), 'utf8');
  // Validate JSON parses
  JSON.parse(raw);
  sections.push(`export const ${constNameFor(file)}: unknown = ${raw.trim()};`);
}

const banner = `// AUTO-GENERATED by scripts/generate-openai-tools-manifests.mjs.
// Do not edit by hand. Re-run \`npm run codegen\` after changing the source
// JSON in @sogni-ai/sogni-protocol.
/* eslint-disable */
`;

await writeFile(outFile, `${banner}\n${sections.join('\n\n')}\n`, 'utf8');

console.log(`[generate-openai-tools-manifests] wrote ${outFile} from @sogni-ai/sogni-protocol (${manifestFiles.length} manifests)`);
